export function parcelFlight(){return `<section class="parcel-flight" aria-label="Special delivery aiming game"><div class="flight-hud"><strong id="flight-cargo">Starch parcel</strong><span id="flight-progress">Delivered 0 of 4</span></div><p class="flight-mission">Which stays in the plant? Which is released? Choose a destination with your aim.</p><div class="flight-arena" id="flight-arena"><div class="flight-destination food-destination" data-destination="starch"><svg viewBox="0 0 80 64" aria-hidden="true"><path d="M6 22 40 4l34 18v36H6Z" fill="#fff0b3" stroke="#163f32" stroke-width="3"/><path d="M20 29h40v22H20ZM20 40h40M33 29v22M47 29v22" fill="none" stroke="#8b6839" stroke-width="3"/></svg><strong>Plant’s food store</strong></div><div class="flight-destination air-destination" data-destination="oxygen"><svg viewBox="0 0 80 64" aria-hidden="true"><path d="M17 46C1 46 1 24 18 23 17 3 46-1 52 18 75 8 85 43 65 46Z" fill="#fffef8" stroke="#265d70" stroke-width="3"/><path d="M21 55h27m9 0h8" stroke="#265d70" stroke-width="3" stroke-linecap="round"/></svg><strong>Open air</strong></div><canvas id="flight-guide" aria-hidden="true"></canvas><div class="launch-ring" id="launch-ring" aria-hidden="true"></div><button type="button" id="flight-parcel" class="flight-parcel" aria-label="Starch parcel. Drag back and release to launch. Or use arrow keys to aim and Space to launch."><span class="cargo-art" aria-hidden="true"></span><strong id="parcel-name">Starch</strong></button><span class="launch-label" id="launch-label">PULL BACK & RELEASE</span><div class="flight-end" id="flight-end" hidden><h2>Deliveries complete!</h2><p><strong>Starch</strong> is stored food.<br><strong>Oxygen</strong> is released into the air.</p><button class="btn yellow" id="flight-replay">Fly again</button></div></div><div class="flight-help"><p id="flight-feedback" role="status" aria-live="polite">Grab the parcel. Pull down and away from your target, then let go.</p><p class="flight-keyboard">Keyboard: Left / Right to aim · Up / Down for power · Space to launch.</p></div><p class="flight-model-note">Parcels represent the products of photosynthesis.</p></section>`}

export function bindParcelFlight(onComplete){
 const $=s=>document.querySelector(s),arena=$('#flight-arena'),parcel=$('#flight-parcel'),canvas=$('#flight-guide'),ctx=canvas.getContext('2d'),feedback=$('#flight-feedback');
 const rounds=[{name:'Starch',kind:'starch',x:50},{name:'Oxygen',kind:'oxygen',x:50},{name:'Oxygen',kind:'oxygen',x:38},{name:'Starch',kind:'starch',x:62}];
 let round=0,mode='ready',vx=0,vy=-90,px=50,py=76,dx=0,dy=0,pointer=null,last=performance.now(),raf=0,timer=0,dead=false;
 const current=()=>rounds[round];
 function place(){parcel.style.left=px+'%';parcel.style.top=py+'%'}
 function reset(){mode='ready';vx=0;vy=-90;dx=dy=0;px=current().x;py=76;parcel.hidden=false;parcel.classList.toggle('is-oxygen',current().kind==='oxygen');$('#parcel-name').textContent=current().name;$('#flight-cargo').textContent=current().name+' parcel';parcel.setAttribute('aria-label',current().name+' parcel. Drag back and release to launch. Or use arrow keys to aim and Space to launch.');$('#flight-progress').textContent=`Delivered ${round} of ${rounds.length}`;$('#launch-ring').style.left=px+'%';$('#launch-label').style.left=px+'%';$('#launch-label').hidden=false;place();drawGuide()}
 function drawGuide(){const r=arena.getBoundingClientRect();ctx.clearRect(0,0,r.width,r.height);if(mode!=='ready'&&mode!=='aiming')return;ctx.strokeStyle='#163f32';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(current().x/100*r.width,.76*r.height);ctx.lineTo(px/100*r.width,py/100*r.height);ctx.stroke();for(let t=.1;t<1.6;t+=.1){const ax=current().x+vx*t,ay=76+vy*t+35*t*t;if(ax<0||ax>100||ay<1||ay>100)break;ctx.beginPath();ctx.fillStyle='#163f32';ctx.arc(ax/100*r.width,ay/100*r.height,Math.max(2,4-t),0,Math.PI*2);ctx.fill()}}
 function launch(){if(mode!=='ready'&&mode!=='aiming')return;mode='flying';pointer=null;px=current().x;py=76;$('#launch-label').hidden=true;drawGuide();place()}
 parcel.onpointerdown=e=>{if(mode!=='ready'||e.button!==0||!e.isPrimary)return;pointer=e.pointerId;mode='aiming';parcel.setPointerCapture(pointer);parcel.focus({preventScroll:true});const r=arena.getBoundingClientRect();dx=(e.clientX-r.left)/r.width*100-px;dy=(e.clientY-r.top)/r.height*100-py;e.preventDefault()};
 parcel.onpointermove=e=>{if(pointer!==e.pointerId||mode!=='aiming')return;const r=arena.getBoundingClientRect();let ax=(e.clientX-r.left)/r.width*100-dx-current().x,ay=(e.clientY-r.top)/r.height*100-dy-76;const length=Math.hypot(ax,ay);if(length>24){ax*=24/length;ay*=24/length}px=current().x+ax;py=76+ay;vx=-ax*5;vy=-ay*5;place();drawGuide()};
 parcel.onpointerup=e=>{if(e.pointerId!==pointer)return;const tooSmall=Math.hypot(vx,vy)<20;if(tooSmall){pointer=null;reset();feedback.textContent='Pull the parcel farther back before releasing.'}else launch();if(parcel.hasPointerCapture(e.pointerId))parcel.releasePointerCapture(e.pointerId)};
 const cancel=e=>{if(e.pointerId===pointer){pointer=null;reset()}};parcel.onpointercancel=parcel.onlostpointercapture=cancel;
 parcel.onkeydown=e=>{if(mode!=='ready')return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' ','Enter'].includes(e.key)){e.preventDefault();if(e.key===' '||e.key==='Enter'){launch();return}if(e.key==='ArrowLeft')vx=Math.max(-100,vx-5);if(e.key==='ArrowRight')vx=Math.min(100,vx+5);if(e.key==='ArrowUp')vy=Math.max(-120,vy-5);if(e.key==='ArrowDown')vy=Math.min(-30,vy+5);drawGuide();parcel.setAttribute('aria-label',`${current().name} parcel. Aim ${vx<0?'left':vx>0?'right':'straight'}, power ${Math.round(-vy)}. Space to launch.`)}};
 function settle(target){mode='waiting';parcel.hidden=true;drawGuide();const right=target===current().kind;if(right){round++;$('#flight-progress').textContent=`Delivered ${round} of ${rounds.length}`;feedback.textContent=target==='starch'?'Delivered! Starch is stored food in the plant.':'Delivered! Oxygen is released into the air.';const destination=arena.querySelector(`[data-destination="${target}"]`);destination.classList.add('delivery-hit');if(round===rounds.length){mode='done';$('#flight-end').hidden=false;onComplete();return}}else feedback.textContent=target?(current().kind==='starch'?'Starch is stored food. Aim for the plant’s food store.':'Oxygen is released. Aim for the open air.'):'Missed the delivery spot. Follow the dotted arc and adjust your aim.';timer=setTimeout(()=>{if(dead)return;arena.querySelectorAll('.delivery-hit').forEach(el=>el.classList.remove('delivery-hit'));reset()},1100)}
 function tick(now){if(dead)return;const dt=Math.min((now-last)/1000,.035);last=now;if(mode==='flying'&&!document.hidden){px+=vx*dt;py+=vy*dt+35*dt*dt;vy+=70*dt;place();if(py>=9&&py<=33){if(px>=7&&px<=37)settle('starch');else if(px>=63&&px<=93)settle('oxygen')}if(mode==='flying'&&(px< -8||px>108||py>108||py< -18))settle(null)}raf=requestAnimationFrame(tick)}
 $('#flight-replay').onclick=()=>{clearTimeout(timer);round=0;$('#flight-end').hidden=true;arena.querySelectorAll('.delivery-hit').forEach(el=>el.classList.remove('delivery-hit'));reset();feedback.textContent='Grab the parcel. Pull down and away from your target, then let go.';parcel.focus({preventScroll:true})};
 const resize=new ResizeObserver(()=>{const r=arena.getBoundingClientRect(),ratio=devicePixelRatio||1;canvas.width=r.width*ratio;canvas.height=r.height*ratio;ctx.setTransform(ratio,0,0,ratio,0,0);drawGuide()});resize.observe(arena);reset();raf=requestAnimationFrame(tick);
 return ()=>{dead=true;clearTimeout(timer);cancelAnimationFrame(raf);resize.disconnect()};
}
